const test = require("node:test");
const assert = require("node:assert/strict");
const { loadApp } = require("../ui/load_app");

const seed = () => [
  { id: 1, name: "Charlie", clips: [], video_filename: null },
  { id: 2, name: "alpha reserve", clips: [], video_filename: null },
  { id: 3, name: "Beta Bowl", clips: [], video_filename: null },
];
const settle = () => new Promise(resolve => setTimeout(resolve, 0));
const cards = app => app.document.querySelectorAll(".project-card");
const names = app => cards(app).map(card => card.dataset.name);
const type = (app, value) => {
  const input = app.document.getElementById("project-search");
  input.value = value;
  input.dispatchEvent(app.document.createEvent("input"));
};
const fixture = (options = {}, initial = seed()) => {
  let projects = initial;
  const historyCalls = [];
  const routes = {
    "GET /api/projects": () => projects,
    "POST /api/projects": () => { projects.push({ id: 4, name: "Delta", clips: [], video_filename: null }); return {}; },
    "DELETE /api/projects/2": () => { projects = projects.filter(p => p.id !== 2); return {}; },
  };
  const history = options.history || { replaceState: (...args) => historyCalls.push(args) };
  return { app: loadApp({ ...options, history, routes }), historyCalls };
};
const clickSort = app => app.document.getElementById("btn-project-sort").click();

test("keeps API order, then toggles ascending and descending", async () => {
  const { app } = fixture(); await settle();
  const container = app.document.getElementById("projects-container");
  const button = app.document.getElementById("btn-project-sort");
  assert.deepEqual(names(app), ["charlie", "alpha reserve", "beta bowl"]);
  assert.equal(container.dataset.sort, undefined);
  clickSort(app); assert.deepEqual(names(app), ["alpha reserve", "beta bowl", "charlie"]);
  assert.equal(container.dataset.sort, "asc"); assert.match(button.textContent, /Z→A/);
  clickSort(app); assert.deepEqual(names(app), ["charlie", "beta bowl", "alpha reserve"]);
  assert.equal(container.dataset.sort, "desc"); assert.match(button.textContent, /A→Z/);
  clickSort(app); assert.deepEqual(names(app), ["alpha reserve", "beta bowl", "charlie"]);
});

test("lowercases names and keeps original tie order both ways", async () => {
  const tied = ["Delta", "delta", "DELTA", "apple"].map((name, i) => ({ id: i + 1, name, clips: [], video_filename: null }));
  const { app } = fixture({}, tied); await settle(); clickSort(app);
  const ids = () => cards(app).map(card => card.querySelector(".delete-btn").dataset.id);
  assert.deepEqual(ids(), ["4", "1", "2", "3"]);
  clickSort(app); assert.deepEqual(ids(), ["1", "2", "3", "4"]);
});

test("sorting preserves the active search state and hash", async () => {
  const { app, historyCalls } = fixture({ location: { hash: "#q=ALP" } }); await settle();
  type(app, "ALP");
  const snapshot = () => ({
    value: app.document.getElementById("project-search").value,
    hidden: Object.fromEntries(cards(app).map(card => [card.dataset.name, card.hidden])),
    count: app.document.getElementById("project-search-count").textContent,
    hash: historyCalls.at(-1),
    noMatch: app.document.getElementById("project-search-empty").hidden,
    empty: app.document.getElementById("projects-empty").hidden,
  });
  const before = snapshot(); clickSort(app);
  assert.deepEqual(snapshot(), before);
  assert.deepEqual(names(app), ["alpha reserve", "beta bowl", "charlie"]);
});

test("toggle is local and leaves location unchanged", async () => {
  const { app } = fixture(); await settle();
  const href = app.evalInApp("window.location.href");
  clickSort(app); clickSort(app);
  assert.equal(app.calls.fetch.length, 1);
  assert.equal(app.evalInApp("window.location.href"), href);
});

test("active ascending sort survives create and delete reloads", async () => {
  const { app } = fixture({ confirmResult: true }); await settle(); clickSort(app); type(app, "alp");
  app.document.getElementById("new-project-name").value = "Delta";
  app.document.getElementById("btn-create-project").click(); await settle();
  assert.equal(app.document.getElementById("project-search").value, "");
  assert.deepEqual(names(app), ["alpha reserve", "beta bowl", "charlie", "delta"]);
  cards(app)[0].querySelector(".delete-btn").click(); await settle();
  assert.deepEqual(app.calls.fetch.filter(call => call.method === "DELETE").map(call => call.path), ["/api/projects/2"]);
  assert.match(app.calls.confirm[0][0], /alpha reserve/);
  assert.deepEqual(names(app), ["beta bowl", "charlie", "delta"]);
  assert.equal(app.document.getElementById("projects-container").dataset.sort, "asc");
});
import os
import re
import shutil
import subprocess

import pytest


def test_project_sort_ui_suite():
    node = shutil.which("node")
    if node is None:
        pytest.skip("node not installed")

    root = os.path.dirname(os.path.dirname(os.path.dirname(__file__)))
    result = subprocess.run(
        [node, "--test", "--test-reporter=tap", "tests/sorting/project_sort.test.js"],
        cwd=root,
        capture_output=True,
        text=True,
        timeout=60,
    )
    out = result.stdout + result.stderr
    assert result.returncode == 0, out
    assert re.search(r"^# pass 5$", out, re.M), out
    assert re.search(r"^# fail 0$", out, re.M), out

